  const chatBottom = useRef<HTMLDivElement>(null);
  const t = (id: string, en: string) => lang === "en" ? en : lang === "ms" ? (labelsMs[id] || id) : id;
  const translated = (label: string) => lang === "en" ? (labelsEn[label] || label) : lang === "ms" ? (labelsMs[label] || label) : label;
  const active = allFeatures.find(f => f.id === activeId) || features[0];
  const parentFeature = features.find(f => f.id === activeId || f.variants?.some(v => v.id === activeId)) || active;
  const visibleFeatures = features.filter(f => !f.hidden);
  const results = resultsByFeature[activeId] || [];
  const fileFields = active.fields.filter(f => f.type === "file");
  const isLocal = active.kind === "local" || activeId === "upscale";
  const filtered = useMemo(() => visibleFeatures.filter(f => `${f.label} ${f.description} ${f.group}`.toLowerCase().includes(query.toLowerCase())), [query, visibleFeatures]);

  useEffect(() => {
    queueMicrotask(()=>{
    setProfile(stored("affgo.profile", "")); setEmail(stored("affgo.profile", "")); setLang(stored("affgo.language", "id")); setTheme(stored("affgo.theme", "light")); setFavorites(stored("affgo.favorites", [])); setCollapsed(stored("affgo.categories", [])); setProducts(stored("affgo.catalog", []));
    const locationId = new URLSearchParams(window.location.search).get("tool"); if (locationId && allFeatures.some(f => f.id === locationId)) setActiveId(locationId);
    });
    Promise.allSettled([request<Session>("/api/session").then(s => { setSession(s); if (s.authenticated && s.user?.email) { setProfile(s.user.email); setEmail(s.user.email); } }), request<{ favorites?: string[]; theme?: string; language?: Lang }>("/api/preferences").then(p => { if (p.favorites) setFavorites(p.favorites); if (p.theme) setTheme(p.theme); if (p.language) setLang(p.language); })]).finally(() => setReady(true));
  }, []);
  useEffect(() => { const cached=formCache.current[activeId];setValues(cached?.values||defaultValues(active));setUploads(cached?.uploads||[]);setError(""); setEditor({ rotate: 0, flipX: false, flipY: false, crop: "original", brightness: 100, contrast: 100, saturation: 100, warmth: 0, highlights: 0, shadows: 0, sharpness: 0, vignette: 0, grain: 0, preset: "Original", scale: activeId === "upscale" ? "2" : "1", width: "", height: "", format: "png" }); }, [activeId,active]);
  useEffect(() => { if (!ready) return; document.documentElement.dataset.theme = theme; document.documentElement.lang = lang; localStorage.setItem("affgo.theme", JSON.stringify(theme)); localStorage.setItem("affgo.language", JSON.stringify(lang)); localStorage.setItem("affgo.favorites", JSON.stringify(favorites)); const timer=window.setTimeout(async()=>{prefsPending.current={favorites,theme,language:lang};if(prefsSaving.current)return;prefsSaving.current=true;while(prefsPending.current){const next=prefsPending.current;prefsPending.current=null;try{await request("/api/preferences",next);}catch{/* Local preferences remain usable offline. */}}prefsSaving.current=false;},400);return()=>clearTimeout(timer); }, [favorites, theme, lang, ready]);
