  useEffect(()=>{if(!mobileOpen)return;const before=document.activeElement as HTMLElement;const old=document.body.style.overflow;document.body.style.overflow="hidden";sidebarRef.current?.querySelector<HTMLButtonElement>("button")?.focus();const handler=(e:KeyboardEvent)=>{if(e.key==="Escape")setMobileOpen(false);if(e.key==="Tab"){const elements=sidebarRef.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input,select,a[href]');if(!elements?.length)return;const first=elements[0],last=elements[elements.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};document.addEventListener("keydown",handler);return()=>{document.body.style.overflow=old;document.removeEventListener("keydown",handler);before?.focus();};},[mobileOpen]);

  function navigate(id: string) { if (working) return;formCache.current[activeId]={values,uploads};setActiveId(id); setMobileOpen(false); setQuery(""); const url = new URL(window.location.href); if(id === "beranda")url.searchParams.delete("tool");else url.searchParams.set("tool", id); window.history.replaceState(null, "", url); window.scrollTo({ top: 0, behavior: "smooth" }); }
  function toggleFavorite(id: string) { setFavorites(v => v.includes(id) ? v.filter(x => x !== id) : [...v, id]); }
  function login(e: React.FormEvent) { e.preventDefault(); if (!email.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return; localStorage.setItem("affgo.profile", JSON.stringify(email.trim()));if(session && !session.authenticated && session.signInUrl){window.top!.location.href=session.signInUrl;return;}setProfile(email.trim());setNotice(t("Profil studio siap digunakan.", "Your studio profile is ready.")); }
  function logout() { setProfile(""); setApiKey(""); localStorage.removeItem("affgo.profile"); if (session?.signOutUrl) window.location.assign(session.signOutUrl); }
  async function addFiles(files: FileList | File[], fieldId: string, multiple = true) {
    if(working)return;setError("");setWorking(true);const next: Upload[] = []; const pendingVideos:Record<string,File>={}; const field = active.fields.find(f => f.id === fieldId);
    try { if(files.length>(multiple?14:1))throw new Error(t("Jumlah file melebihi batas input ini.","Too many files for this input."));for (const file of Array.from(files)) {
        if (field?.role === "video" || field?.accept?.includes("video")) {const countField=active.fields.find(f=>f.role==="count");const frameCount=Math.max(1,Math.min(10,Number(countField?values[countField.id]:5)||5));const frames = await extractVideoFrames(file, frameCount); frames.forEach(frame => next.push({ ...frame, id: crypto.randomUUID(), fieldId }));pendingVideos[fieldId]=file; }
        else { const processed = isLocal ? {data:(await readFile(file)).split(",")[1],mimeType:file.type} : await prepareImage(file); if(isLocal && (!/^image\/(png|jpeg|webp)$/.test(file.type) || file.size>25*1024*1024)) throw new Error(t("Gunakan PNG, JPG, WEBP dengan ukuran maksimal 25 MB.","Use PNG, JPG, or WEBP under 25 MB.")); next.push({id:crypto.randomUUID(),name:file.name,...processed,fieldId}); }
      }
      const combined = [...uploads.filter(u => u.fieldId !== fieldId), ...next]; if(!isLocal && (combined.length>14 || combined.reduce((n,u)=>n+u.data.length*.75,0)>12*1024*1024)) throw new Error(t("Maksimal 14 referensi dengan total ukuran 12 MB.","Maximum 14 references with a combined size of 12 MB."));Object.assign(sourceVideos.current,pendingVideos);setUploads(combined);
      if(field?.role === "video") setNotice(`${next.length} ${t("frame video siap dianalisis.","video frames are ready to analyze.")}`);
    } catch (e) { setError((e as Error).message); } finally { setWorking(false); }
  }
  function removeUpload(id:string){const removed=uploads.find(u=>u.id===id);if(!removed)return;const isVideo=active.fields.some(f=>f.id===removed.fieldId&&(f.role==="video"||f.accept?.includes("video")));const remaining=isVideo?uploads.filter(u=>u.fieldId!==removed.fieldId):uploads.filter(u=>u.id!==id);if(isVideo)delete sourceVideos.current[removed.fieldId];formCache.current[activeId]={values,uploads:remaining};setUploads(remaining);}
  async function generate(kindOverride?: "text" | "image" | "audio", promptOverride?: string) {
    setError(""); setWorking(true); cancelRequested.current=false;
    const countField=active.fields.find(f=>f.role==="count"); const kind=kindOverride || (active.kind === "audio" ? "audio" : active.kind === "text" || active.kind === "video" ? "text" : "image"); const count=kind==="image"?Math.max(1,Math.min(10,Number(countField?values[countField.id]:1)||1)):1;
    const prompt = promptOverride || Object.entries(values).filter(([k,v]) => v !== "" && k!==countField?.id).map(([k,v]) => {const field=active.fields.find(f => f.id === k);return `${field?.label || k}: ${field?.options?.find(o=>o.value===String(v))?.label||v}`;}).join("\n") || active.description;
    const base={featureId:activeId,options:{...values,...(countField&&kind==="image"?{[countField.id]:"1"}:{})},images:uploads.map(({data,mimeType,fieldId})=>({data,mimeType,fieldId})),...(apiKey?{apiKey}:{})};
    const append=(items:Result[])=>setResultsByFeature(previous=>({...previous,[activeId]:[...items,...(previous[activeId]||[])]}));
    try {if(active.capability==="video-analysis"){const videoField=active.fields.find(f=>f.role==="video");const source=videoField&&sourceVideos.current[videoField.id];if(source&&videoField&&uploads.some(u=>u.fieldId===videoField.id)){const frameCount=Math.max(1,Math.min(10,Number(countField?values[countField.id]:5)||5));const frames=await extractVideoFrames(source,frameCount);base.images=frames.map(frame=>({...frame,fieldId:videoField.id}));}}let plan="";if(active.capability==="storyboard"){setProgress({current:0,total:count+1});const planning=await request<{results:Result[];error?:string}>("/api/generate",{...base,kind:"text",prompt:`Create a coherent ${count}-scene storyboard with numbered scenes and detailed visual direction.\n${prompt}`});if(planning.error)throw new Error(planning.error);plan=planning.results.map(r=>r.text||"").join("\n");if(!plan.trim())throw new Error("Storyboard plan was empty.");append(planning.results);}
      for(let i=0;i<count;i++){if(cancelRequested.current)break;setProgress({current:i+1,total:count});const scenePrompt=plan?`Render only scene ${i+1} of this storyboard. Maintain visual consistency.\n${plan}`:count>1?`${prompt}\nCreate result ${i+1} of ${count}, consistent with the chosen style and reference.`:prompt;const output=await request<{results:Result[];error?:string}>("/api/generate",{...base,kind,prompt:scenePrompt,options:{...base.options,sequenceIndex:i+1,sequenceTotal:count}});if(output.error)throw new Error(output.error);if(!output.results?.length)throw new Error(t("Provider tidak mengembalikan hasil. Silakan coba lagi.","The provider returned no result. Please try again."));if(activeId==="beranda")setMessages(previous=>[...previous,{role:"assistant",text:output.results.map(r=>r.text||"").join("\n")}]);else append(output.results.slice(0,kind==="image"?1:undefined));}
      setNotice(cancelRequested.current?t("Proses lanjutan dihentikan.","Remaining generation stopped."):t("Hasil siap!","Your result is ready!"));
    } catch(e){setError((e as Error).message);}finally{setWorking(false);setProgress({current:0,total:0});}
  }
  function chatSend(e?: React.FormEvent) { e?.preventDefault(); if (!chatInput.trim() || working) return; const question = chatInput.trim(); const conversation=[...messages.slice(-10),{role:"user",text:question}].map(m=>`${m.role}: ${m.text}`).join("\n\n"); setMessages(previous => [...previous, { role: "user", text: question }]); setChatInput(""); generate("text", conversation); }
  async function processImage(e: React.FormEvent) {
    e.preventDefault(); if (!uploads.length) { setError(t("Upload foto terlebih dahulu.", "Upload an image first.")); return; } setWorking(true); setError("");
    try { const image = await loadImage(`data:${uploads[0].mimeType};base64,${uploads[0].data}`); let sx = 0, sy = 0, sw = image.naturalWidth, sh = image.naturalHeight; const ratios: Record<string, number> = { "1:1": 1, "4:5": .8, "9:16": 9 / 16, "16:9": 16 / 9, "3:4": .75 }; if (editor.crop !== "original") { const ratio = ratios[editor.crop]; if (sw / sh > ratio) { sw = sh * ratio; sx = (image.naturalWidth - sw) / 2; } else { sh = sw / ratio; sy = (image.naturalHeight - sh) / 2; } }
      const rotated = editor.rotate % 180 !== 0; const scale = Number(editor.scale); const width = Number(editor.width) || Math.round((rotated ? sh : sw) * scale); const height = Number(editor.height) || Math.round((rotated ? sw : sh) * scale); if (width < 1 || height < 1 || width > 8192 || height > 8192 || width * height > 32000000) throw new Error(t("Dimensi hasil maksimal 8192 px dan 32 megapiksel.", "Output is limited to 8192 px and 32 megapixels."));
      const canvas = document.createElement("canvas"); canvas.width = width; canvas.height = height; const ctx = canvas.getContext("2d"); if (!ctx) throw new Error("Canvas unavailable"); if (editor.format === "jpeg") { ctx.fillStyle = "#fff"; ctx.fillRect(0,0,width,height); } ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = "high"; ctx.filter = `brightness(${editor.brightness}%) contrast(${editor.contrast}%) saturate(${editor.saturation}%)`; ctx.translate(width / 2, height / 2); ctx.rotate(editor.rotate * Math.PI / 180); ctx.scale(editor.flipX ? -1 : 1, editor.flipY ? -1 : 1); ctx.drawImage(image, sx, sy, sw, sh, -(rotated ? height : width) / 2, -(rotated ? width : height) / 2, rotated ? height : width, rotated ? width : height); ctx.setTransform(1,0,0,1,0,0);ctx.filter="none";finishPixels(ctx,width,height,editor);const result = { id: crypto.randomUUID(), kind: "image", mimeType: `image/${editor.format}`, url: canvas.toDataURL(`image/${editor.format}`, .94) }; setResultsByFeature(previous => ({ ...previous, [activeId]: [result, ...(previous[activeId] || [])] })); setNotice(`${width} × ${height} px · ${t("Siap diunduh", "Ready to download")}`);
    } catch (e) { setError((e as Error).message); } finally { setWorking(false); }
  }
  async function download(result: Result) { if (result.text) { const url = URL.createObjectURL(new Blob([result.text], { type: "text/plain;charset=utf-8" })); const a = document.createElement("a"); a.href = url; a.download = `affiliate-go-${activeId}.txt`; a.click(); URL.revokeObjectURL(url); return; } if (!result.url) return; try { const response = await fetch(result.url); if (!response.ok) throw new Error("Download failed"); const blob = await response.blob(); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = `affiliate-go-${result.id}.${blob.type.split("/")[1] || "png"}`; a.click(); URL.revokeObjectURL(url); } catch { window.open(result.url, "_blank", "noopener,noreferrer"); } }
  async function copy(text: string) { try { await navigator.clipboard.writeText(text); setNotice(t("Teks berhasil disalin", "Text copied")); } catch { setError(t("Clipboard tidak tersedia. Pilih lalu salin teks secara manual.", "Clipboard is unavailable. Select and copy the text manually.")); } }
  async function openHistory() { setDialog("history"); setHistoryLoading(true); try { const response = await request<{ items: HistoryItem[] }>("/api/history"); setHistory(response.items || []); } catch (e) { setError((e as Error).message); } finally { setHistoryLoading(false); } }
  function saveProduct(e: React.FormEvent) { e.preventDefault(); try { const url = new URL(productDraft.url); if (!/^https?:$/.test(url.protocol)) throw new Error(); setProducts(p => [...p, { id: crypto.randomUUID(), ...productDraft }]); setProductDraft({ name: "", description: "", price: "", url: "" }); setDialog(null); setNotice(t("Produk ditambahkan ke etalase lokal.", "Product added to your local storefront.")); } catch { setError(t("Masukkan tautan produk http atau https yang valid.", "Enter a valid http or https product link.")); } }

  function navItem(feature: Feature, favorite = false) { return <div className={`nav-item ${parentFeature.id === feature.id ? "selected" : ""} ${feature.id === "beranda" ? "nav-home" : ""}`} key={`${favorite ? "fav-" : ""}${feature.id}`}><button className="nav-feature" onClick={() => navigate(feature.id)} disabled={working} aria-current={parentFeature.id === feature.id ? "page" : undefined}><Icon name={feature.iconId} size={18} /><span>{translated(feature.label.replace(/\s*NEW$/, ""))}</span>{feature.isNew && <b className="new-badge">NEW</b>}</button>{feature.id !== "beranda" && <button className={`favorite-button ${favorites.includes(feature.id) ? "is-favorite" : ""}`} aria-label={`${favorites.includes(feature.id) ? t("Hapus favorit", "Remove favorite") : t("Tambah favorit", "Add favorite")}: ${feature.label}`} onClick={() => toggleFavorite(feature.id)}><Star size={14} fill={favorites.includes(feature.id) ? "currentColor" : "none"} /></button>}</div>; }
  function fieldControl(field: FeatureField) { const value = values[field.id] ?? ""; const change = (v: string | number) => setValues(previous => ({ ...previous, [field.id]: v })); return <div className={`form-field ${field.type === "textarea" ? "field-full" : ""}`} key={field.id}><label htmlFor={`field-${field.id}`}>{field.label}{field.required && <span className="required"> *</span>}</label>{field.type === "textarea" ? <textarea id={`field-${field.id}`} rows={4} value={String(value)} onChange={e => change(e.target.value)} placeholder={field.placeholder || field.help || t("Tuliskan detail yang kamu inginkan…", "Describe what you have in mind…")} required={field.required} /> : field.type === "select" ? <select id={`field-${field.id}`} value={String(value)} onChange={e => change(e.target.value)}>{field.options?.map(option => <option key={option.value} value={option.value}>{option.label}</option>)}</select> : field.type === "choice" ? <div className="choice-group">{field.options?.map(option => <button key={option.value} type="button" className={`choice ${String(value) === option.value ? "chosen" : ""}`} aria-pressed={String(value) === option.value} onClick={() => change(option.value)}>{option.label}</button>)}</div> : field.type === "range" ? <div className="range-field"><input id={`field-${field.id}`} type="range" min={field.min ?? 0} max={field.max ?? 100} step={field.step ?? 1} value={Number(value)} onChange={e => change(Number(e.target.value))} /><output>{String(value)}</output></div> : <input id={`field-${field.id}`} type={field.type === "number" || field.type === "color" ? field.type : "text"} min={field.min} max={field.max} value={String(value)} onChange={e => change(field.type === "number" ? Number(e.target.value) : e.target.value)} required={field.required} placeholder={field.placeholder || field.help || ""} />}{field.help && <small>{field.help}</small>}</div>; }
  function uploadArea(fieldId: string, title: string, multiple = true) { const current = uploads.filter(u => u.fieldId === fieldId); const isVideo = active.fields.find(f=>f.id===fieldId)?.role === "video"; return <div className="upload-field" key={fieldId}><label className="upload-title" htmlFor={`upload-${fieldId}`}>{title}</label><label className={`upload-drop ${current.length ? "upload-compact" : ""}`} htmlFor={`upload-${fieldId}`} onDragOver={e => { e.preventDefault(); }} onDrop={e => { e.preventDefault(); addFiles(e.dataTransfer.files, fieldId, multiple); }}><span className="upload-symbol"><UploadCloud size={28} /></span><strong>{current.length ? t("Ganti foto", "Replace photo") : isVideo?t("Klik atau seret video ke sini", "Click or drop your video here"):t("Klik atau seret foto ke sini", "Click or drop your photo here")}</strong><span>{isVideo?"MP4, MOV, WEBM · 200 MB":"PNG, JPG, WEBP · 25 MB"}</span><input id={`upload-${fieldId}`} className="visually-hidden" type="file" accept={isVideo?"video/mp4,video/webm,video/quicktime":"image/png,image/jpeg,image/webp"} multiple={multiple} disabled={working} onChange={e => e.target.files && addFiles(e.target.files, fieldId, multiple)} /></label>{current.length > 0 && <div className="upload-thumbnails">{current.map(u => <div key={u.id} className="upload-thumb"><img src={`data:${u.mimeType};base64,${u.data}`} alt={u.name} /><span title={u.name}>{u.name}</span><button type="button" aria-label={`${t("Hapus", "Remove")} ${u.name}`} disabled={working} onClick={() => removeUpload(u.id)}><X size={14} /></button></div>)}</div>}</div>; }
  function errorPanel() { return error && <div className="error-panel" role="alert"><Info size={20} /><div><strong>{t("Permintaan belum berhasil", "Request could not be completed")}</strong><p>{error}</p><button type="button" className="text-button" onClick={() => setDialog("settings")}>{t("Buka pengaturan AI", "Open AI settings")} <ArrowRight size={14} /></button></div><button type="button" className="icon-button" aria-label={t("Tutup pesan", "Dismiss error")} onClick={() => setError("")}><X size={16} /></button></div>; }
  function resultCards(items: Result[]) { return <div className="results-grid">{items.map((result, index) => <article className={`result-card ${result.kind === "text" ? "result-text" : ""}`} key={result.id}>{result.kind === "image" && result.url ? <button className="result-image-button" onClick={() => setPreview(result)} aria-label={t("Lihat gambar ukuran penuh", "View full size image")}><img src={result.url} alt={`${active.label} — ${t("hasil", "result")} ${index + 1}`} loading="lazy" /><span><Expand size={18} /></span></button> : result.kind === "audio" && result.url ? <AudioPlayer url={result.url} lang={lang} /> : <div className="text-result-content">{result.text}</div>}<div className="result-card-actions"><span>{result.kind === "image" ? t("Foto", "Image") : result.kind === "audio" ? "Audio" : t("Teks", "Text")} {index + 1}</span><div>{result.text && <button className="icon-button" title={t("Salin", "Copy")} onClick={() => copy(result.text!)}><Copy size={17} /></button>}<button className="icon-button" title={t("Unduh hasil", "Download result")} onClick={() => download(result)}><Download size={18} /></button><button className="icon-button" title={t("Hapus dari layar", "Remove from view")} onClick={() => setResultsByFeature(p => ({ ...p, [activeId]: (p[activeId] || []).filter(r => r.id !== result.id) }))}><Trash2 size={16} /></button></div></div></article>)}</div>; }

